package com.yeyamo_mobile.api.interaction_service.application;import com.yeyamo_mobile.api.interaction_service.application.port.InteractionOutboxPort;import com.yeyamo_mobile.api.interaction_service.infrastructure.persistence.*;import org.junit.jupiter.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class GenericInteractionServiceTest{@Test void likeIsIdempotent(){GenericInteractionRepository repo=mock(GenericInteractionRepository.class);InteractionOutboxPort outbox=mock(InteractionOutboxPort.class);GenericInteractionEntity existing=new GenericInteractionEntity();existing.status=GenericInteractionEntity.Status.ACTIVE;when(repo.findByTargetTypeAndTargetIdAndUserIdAndInteractionType(GenericInteractionEntity.TargetType.ARTWORK,"art-1","user",GenericInteractionEntity.Type.LIKE)).thenReturn(Optional.empty(),Optional.of(existing));GenericInteractionService service=new GenericInteractionService(repo,outbox);service.add(GenericInteractionEntity.TargetType.ARTWORK,"art-1",GenericInteractionEntity.Type.LIKE,"user",null,null,"c");assertSame(existing,service.add(GenericInteractionEntity.TargetType.ARTWORK,"art-1",GenericInteractionEntity.Type.LIKE,"user",null,null,"c"));verify(repo,times(1)).save(any());verify(outbox,times(1)).append(eq("ArtworkLiked"),any(),any(),eq("user"),eq("c"),any());}}
